// BWP as a course for the shared practice engine in math.js: Versicherungen and Investitionsrechnung, with their own labs.
(() => {
  const B = window.WWBwp, M = window.WWMath, { rich } = M;
  const V = 'Versicherungen', I = 'Investitionsrechnung', X = 'Extra – kein SA-Stoff';
  const TOPICS = [
    { id: 'prinzip', group: V, title: 'Versicherungsprinzip', sub: 'Risikogemeinschaft, Voraussetzungen, Begriffe', lab: null, intro: 'Viele zahlen eine kleine Prämie in einen Topf, damit die wenigen, die einen Schaden haben, nicht allein dastehen.',
      rules: [['Prinzip', 'Risikogemeinschaft: alle für einen', 'Die Prämien vieler fließen in den Versicherungspool, daraus werden die Schäden bezahlt.'], ['Voraussetzungen', 'Gefahrengemeinschaft, Ungewissheit, Berechenbarkeit, Messbarkeit', 'Viele mit gleichem Risiko, unklar ob und wann, statistisch schätzbar, in Geld bezifferbar.'], ['Begriffe', 'Prämie ↔ Versicherungssumme', 'Die Prämie zahlt der Versicherungsnehmer, die Versicherungssumme ist das Höchste, was die Versicherung im Schadensfall zahlt.'], ['Gesetzlich vs. privat', 'Pflicht und einkommensabhängig ↔ Vertrag und risikoabhängig', 'Die Sozialversicherung ist nicht gewinnorientiert, private Versicherungen schon.']],
      pitfalls: ['**Prämie** und **Versicherungssumme** nicht verwechseln: Die eine zahlt man, die andere bekommt man.', 'Ein Schaden, der sicher eintritt, ist nicht versicherbar: Es fehlt die **Ungewissheit**.', 'Der **Versicherungswert** ist der tatsächliche Wert der Sache, nicht die vereinbarte Summe.'] },
    { id: 'risiko', group: V, title: 'Risikopolitische Maßnahmen', sub: 'Vermeiden, vermindern, überwälzen, selbst tragen', lab: null, intro: 'Jedes Unternehmen ist Risiken ausgesetzt. Es kann sie vermeiden, vermindern, auf andere überwälzen oder selbst tragen.',
      rules: [['Risiko vermeiden', 'Auf das riskante Geschäft verzichten', 'Das Risiko entsteht gar nicht, aber auch die Chance auf Gewinn fällt weg.'], ['Risiko vermindern', 'Wahrscheinlichkeit oder Höhe des Schadens senken', 'Alarmanlage, Sprinkler, Wartung, Schulungen, Datensicherung, Bonitätsprüfung, Risikostreuung.'], ['Risiko überwälzen', 'Ein anderer trägt den finanziellen Schaden', 'Durch eine Versicherung oder vertraglich, z. B. Leasing oder Lieferbedingungen.'], ['Risiko selbst tragen', 'Der Betrieb zahlt den Schaden selbst', 'Bei kleinen Schäden, mit Selbstbehalt oder Rücklagen. Das allgemeine Unternehmerrisiko trägt man immer selbst.'], ['Welche Maßnahme wann?', 'Hoch und häufig: vermeiden · hoch und selten: überwälzen', 'Klein und häufig: vermindern · klein und selten: selbst tragen.']],
      pitfalls: ['Eine Versicherung **vermeidet** kein Risiko: Der Schaden kann trotzdem passieren, nur die Folgen trägt ein anderer (**überwälzen**).', '**Rücklagen** und **Selbstbehalt** heißen: selbst tragen.', 'Lieferanten aufteilen (Risikostreuung) **vermindert** das Risiko.'] },
    { id: 'sv', group: V, title: 'Gesetzliche Sozialversicherung', sub: 'Kranken, Unfall, Pension, Arbeitslosigkeit', lab: null, intro: 'Die Sozialversicherung ist Pflicht und sichert die großen Lebensrisiken ab.',
      rules: [['Krankenversicherung', 'Arzt, Krankenhaus, Medikamente, Krankengeld, Wochengeld, Vorsorge', 'Kinder sind bis 18, in Ausbildung bis 27 bei den Eltern mitversichert.'], ['Unfallversicherung', 'Arbeitsunfälle (inkl. Arbeitsweg) und Berufskrankheiten', 'Erste Hilfe, Behandlung, Rehabilitation und Geldleistungen bei Erwerbsunfähigkeit.'], ['Pensionsversicherung', 'Eigenpension und Hinterbliebenenpension', 'Umlageverfahren (Generationenvertrag): Die Erwerbstätigen zahlen die Pensionen.'], ['Arbeitslosenversicherung', 'Arbeitslosengeld, danach Notstandshilfe (AMS)', 'Anspruch: 52 Wochen Beschäftigung in den letzten zwei Jahren, arbeitsfähig und arbeitswillig. Mindestens 20 Wochen.'], ['Finanzierung', 'Arbeitnehmer und Arbeitgeber anteilig, nach dem Einkommen', 'Reichen die Beiträge nicht, zahlt der Staat dazu.']],
      pitfalls: ['Ein **Freizeitunfall** ist kein Fall für die Unfallversicherung: Die Behandlung zahlt die Krankenversicherung.', 'Auch der **Weg zur Arbeit** zählt zum Arbeitsunfall.', 'Im Krankenstand zahlt **zuerst der Arbeitgeber** das Entgelt weiter, erst bei langer Krankheit die ÖGK.', 'Nur die erste Säule der Pensionsvorsorge ist gesetzlich, betriebliche und private Vorsorge sind freiwillig.'] },
    { id: 'privat', group: V, title: 'Private Versicherungen', sub: 'Personen- und Vermögensversicherungen', lab: null, intro: 'Private Versicherungen schließt man freiwillig ab, um Lücken der Sozialversicherung und das eigene Vermögen abzusichern.',
      rules: [['Personenversicherung', 'Lebens-, private Kranken-, private Unfallversicherung', 'Lebensversicherung: Erlebens-, Ablebens- und Rentenversicherung.'], ['Unvorhergesehene Aufwendungen', 'Haftpflicht, Rechtsschutz, Kfz-Haftpflicht', 'Man muss für einen Schaden aufkommen, den man anderen zufügt, oder einen Rechtsstreit führen.'], ['Versicherung von Gütern', 'Haushalt, Wohngebäude, Kasko, Kredit, Transport', 'Eine eigene Sache wird beschädigt oder geht verloren.'], ['Ertragsentgang', 'Betriebsunterbrechungsversicherung', 'Bei vorübergehender Schließung: entgangener Gewinn und laufende Kosten.'], ['Bündelversicherung', 'Mehrere Verträge in einem Versicherungsschein', 'Typisch für Eigenheim und Kfz. In Österreich enthält die Haushaltsversicherung meist eine private Haftpflicht.']],
      pitfalls: ['Wer **anderen** schadet, braucht die **Haftpflicht**, wer **sich selbst** schützt, eine Sach- oder Personenversicherung.', 'Haushaltsversicherung = Inhalt der Wohnung, **Wohngebäudeversicherung** = das Gebäude selbst.', 'Ablebensversicherung zahlt beim Tod, **Erlebensversicherung** am Ende der Laufzeit.'] },
    { id: 'invest', group: I, title: 'Investitionen: Arten und Prozess', sub: 'Investitionsgut, Anlass, Phasen, Kriterien', lab: null, intro: 'Eine Investition bindet Kapital für lange Zeit. Darum wird sie geplant, bewertet, durchgeführt und kontrolliert.',
      rules: [['Investitionsgut', 'Sach-, Finanz- und immaterielle Investition', 'Maschine · Wertpapiere, Beteiligungen · Patente, Lizenzen.'], ['Investitionsanlass', 'Neu-, Ersatz-, Rationalisierungs-, Erweiterungsinvestition', 'Erstmals · gleichartig ersetzen · effizienter · mehr Kapazität.'], ['Investitionsprozess', 'Planung → Entscheidung → Durchführung → Kontrolle', 'Planung: Bedarf, Kriterien, Angebote. Entscheidung: bewerten, Finanzierung prüfen, kaufen.'], ['Kriterien', 'Quantitativ (Zahlen) und qualitativ (Soft Facts)', 'Kosten, Gewinn, Rentabilität ↔ Umwelt, Qualität, Service, Arbeitsschutz.'], ['Bilanz', 'Investition = Mittelverwendung (Aktiva), Finanzierung = Mittelherkunft (Passiva)', 'Ohne Finanzplanung keine Investitionsentscheidung.']],
      pitfalls: ['Ein **zusätzliches** Gerät ist eine Erweiterung, ein **gleichartiger** Ersatz eine Ersatzinvestition.', 'Effizienter ersetzen = **Rationalisierung**, auch wenn das alte Gerät noch funktioniert.', 'Software, Patente und Marken sind **immaterielle** Investitionen.'] },
    { id: 'kosten', group: I, title: 'Kostenvergleich', sub: 'Kalk. Zinsen, Abschreibung, Stückkosten, kritische Menge', lab: 'krit', intro: 'Gewählt wird die Alternative mit den niedrigsten durchschnittlichen Kosten pro Jahr, bei verschiedener Kapazität pro Stück.',
      rules: [['Kalk. Zinsen', '(AK + RW) : 2 · Zinssatz', 'Verzinst wird das durchschnittlich gebundene Kapital.'], ['Kalk. Abschreibung', '(AK − RW) : Nutzungsdauer', 'Der Restwert wird nicht abgeschrieben.'], ['Gesamtkosten', 'Kalk. Zinsen + kalk. Abschreibung + laufende Betriebskosten', 'Laufend = fixe Betriebskosten + variable Kosten je Stück · Menge.'], ['Stückkosten', 'Gesamtkosten : Ausbringungsmenge', 'Bei unterschiedlicher Kapazität entscheiden die Stückkosten.'], ['Kritische Menge', 'Differenz der Fixkosten : Differenz der variablen Kosten je Einheit', 'Fixkosten = AfA + Zinsen. Darüber gewinnt die Alternative mit den niedrigeren variablen Kosten.']],
      pitfalls: ['Zinsen: Restwert **addieren** und durch 2. Abschreibung: Restwert **abziehen**.', 'Die Anschaffungskosten selbst sind **keine** jährlichen Kosten, sie stecken in der Abschreibung.', 'Kritische Menge: oben **Fixkosten**, unten **variable Kosten**, jeweils größer minus kleiner.'] },
    { id: 'gewinn', group: I, title: 'Gewinnvergleich', sub: 'Erlöse minus Gesamtkosten', lab: null, intro: 'Unterscheiden sich Menge oder Qualität, reicht der Kostenvergleich nicht. Dann zählen auch die Erlöse.',
      rules: [['Gewinn', 'Erlöse − Gesamtkosten', 'Erlöse = Erlös je Stück · Kapazität.'], ['Wann?', 'Unterschiedliche Kapazität oder Qualität', 'Dann sind verschiedene Mengen oder Verkaufspreise möglich.'], ['Entscheidung', 'Höchster Gewinn pro Periode', 'Nicht der höchste Umsatz.'], ['Grenzen', 'Durchschnittswerte, kein Zeitwert, Erlöse schwer zurechenbar', 'Und: Der Gewinn sagt nichts über die Verzinsung des Kapitals.']],
      pitfalls: ['Kalk. Zinsen und Abschreibung sind **auch Kosten** und werden abgezogen.', 'Die Erlöse mit der **eigenen** Kapazität jeder Alternative rechnen.', 'Mehr Umsatz heißt nicht mehr Gewinn.'] },
    { id: 'renta', group: I, title: 'Rentabilität und Amortisation', sub: 'Verzinsung und Rückflussdauer', lab: 'amort', intro: 'Wie gut verzinst sich das eingesetzte Kapital, und wie schnell kommt es zurück?',
      rules: [['Ø Kapitaleinsatz', '(AK + RW) : 2', 'Dasselbe Kapital wie bei den kalk. Zinsen.'], ['Rentabilität', '(Gewinn + kalk. Zinsen) · 100 : Ø Kapitaleinsatz', 'Vereinfacht (wenn verlangt): Gewinn · 100 : Ø Kapitaleinsatz.'], ['Bei Kostenersparnis', 'Kostenersparnis · 100 : Ø Kapitaleinsatz', 'Für Rationalisierungen ohne eigene Erlöse, hier ohne Zinsen.'], ['Amortisationsdauer', '(AK − RW) : (Gewinn + kalk. Abschreibung)', 'Bei Rationalisierung: (AK − RW) : jährliche Kostenersparnis.'], ['Deutung', 'Höchste Rentabilität, kürzeste Rückflussdauer', 'Kürzere Amortisation = weniger Risiko, sagt aber nichts über den Gewinn danach.']],
      pitfalls: ['Durch den **durchschnittlichen** Kapitaleinsatz teilen, nicht durch die Anschaffungskosten.', 'Laut Buch und Formelsammlung kommen die **kalk. Zinsen zum Gewinn dazu**. Die vereinfachte Formel nur, wenn sie verlangt ist.', 'Bei der Amortisation fließt die **Abschreibung** mit zurück: Gewinn + AfA.'] },
    { id: 'vertrag', group: X, title: 'Vertrag und Schadensfall', sub: 'Antrag, Polizze, Obliegenheiten, Kündigung', lab: null, intro: 'Erst wenn die erste Prämie bezahlt ist, besteht ein gültiger Versicherungsvertrag.',
      rules: [['Ablauf', 'Anbahnung → Antrag → Prüfung → Polizze und Prämienschein → erste Prämie', 'Die erste Prämie muss meist binnen 14 Tagen bezahlt werden. Vorläufiger Schutz (Deckungszusage) ist möglich.'], ['Schadensfall', 'Schaden mindern → unverzüglich melden → interne Bearbeitung', 'Bei Einbruch, Diebstahl, Raub, Feuer oder Explosion zusätzlich Anzeige bei der Polizei.'], ['Keine Leistung', 'Vorsatz, verletzte Obliegenheiten, Prämie nicht bezahlt', 'Kulanz = freiwillige Leistung in einem nicht gedeckten Fall.'], ['Vertragsende', 'Kündigung, außerordentliche Kündigung, Interessenwegfall, Konkurs des Versicherers', 'Interessenwegfall: Die versicherte Sache oder Gefahr fällt weg, z. B. Auto verkauft.']],
      pitfalls: ['Unterschreiben allein reicht nicht: **ohne bezahlte erste Prämie kein Schutz**.', 'Polizze und Prämienschein stellt die **Versicherung** aus, den Antrag stellt der **Kunde**.', 'Versicherungsnehmer und Begünstigter können **verschiedene Personen** sein.'] },
    { id: 'leistung', group: X, title: 'Versicherungsleistung', sub: 'Unterversicherung, Selbstbehalt, Erstrisiko', lab: 'unter', intro: 'Wie viel die Versicherung zahlt, hängt von der Art der Versicherung und vom Verhältnis zwischen Versicherungssumme und Versicherungswert ab.',
      rules: [['Summenversicherung', 'Feste Summe, egal wie hoch der Schaden ist', 'Lebens- und Unfallversicherung.'], ['Schadensversicherung', 'Gezahlt wird der tatsächliche Schaden', 'Erstrisiko (bis zur Summe), mit Selbstbehalt (Schaden − Selbstbehalt) oder Vollwert.'], ['Voll- und Überversicherung', 'Summe ≥ Wert: der ganze Schaden wird ersetzt', 'Eine Überversicherung bringt nichts außer höherer Prämie.'], ['Unterversicherung', 'Entschädigung = Versicherungssumme · Schaden : Versicherungswert', 'Nur der aliquote (anteilige) Teil wird ersetzt. Dagegen hilft eine Wertanpassungsklausel.'], ['Neuwert und Zeitwert', 'Neu kaufen ↔ Wert heute mit Alter und Abnutzung', 'Versicherungen begrenzen gerne auf den niedrigeren Zeitwert.']],
      pitfalls: ['Bei Unterversicherung **nie den vollen Schaden** ersetzen: Summe · Schaden : Wert.', 'Liegt der Schaden **unter dem Selbstbehalt**, zahlt die Versicherung nichts.', 'Höchstgrenzen gelten pro Schadensart. Der Selbstbehalt wird pro **Schadensfall** einmal abgezogen.'] },
    { id: 'kfz', group: X, title: 'Kfz und Bonus-Malus', sub: 'Haftpflicht, Kasko, Prämienstufen', lab: 'bonus', intro: 'Die Kfz-Haftpflicht ist Pflicht und zahlt Schäden bei anderen. Für das eigene Auto braucht man eine Kasko.',
      rules: [['Kfz-Haftpflicht', 'Pflicht: Schäden an anderen Personen, Fahrzeugen und Sachen', 'Die Prämie hängt v. a. von der Motorleistung und der Bonus-Malus-Stufe ab.'], ['Teilkasko', 'Diebstahl, Brand, Wild, Lawinen, Sturm, Hagel, Hochwasser', 'Freiwillig, für das eigene Auto.'], ['Vollkasko', 'Teilkasko + selbstverschuldete Unfälle + Vandalismus', 'Lohnt sich vor allem bei Neuwagen.'], ['Bonus-Malus', 'Start Stufe 9 · schadenfrei −1 · je Schadensfall +3', 'Stufen 0–17 von 50 % bis 200 % der Grundprämie.'], ['Neue Prämie', 'Prämie : alter Prozentsatz · neuer Prozentsatz', 'Zuerst auf 100 % zurückrechnen, dann den neuen Prozentsatz nehmen.']],
      pitfalls: ['Die **Haftpflicht zahlt nie den Schaden am eigenen Auto**.', 'Ein Unfall bringt **drei** Stufen Richtung Malus, nicht eine.', 'Polizei: bei Verletzten immer, bei Blechschaden nur, wenn der Gegner fehlt, sich nicht amtlich ausweisen kann oder fremdes Eigentum, Öffentliches oder ein Tier betroffen ist.'] },
  ];
  const FIG = {
    prinzip: '<path d="M10 30a22 22 0 0 1 44 0z"/><path class="a" d="M32 30v14a5 5 0 0 1-10 0"/>',
    risiko: '<path d="M32 8 6 50h52z"/><path class="a" d="M32 24v12M32 42v.1"/>',
    sv: '<path d="M32 8 12 16v12c0 12 9 20 20 24 11-4 20-12 20-24V16z"/><path class="a" d="M32 20v20M22 30h20"/>',
    privat: '<path d="M12 50V26l20-16 20 16v24z"/><path class="a" d="M26 50V36h12v14"/>',
    vertrag: '<path d="M16 8h24l10 10v38H16z"/><path class="a" d="M22 28h20M22 36h20M22 44h12"/>',
    leistung: '<path d="M10 48h44"/><path d="M14 48V20h10v28M30 48V30h10v18"/><path class="a" d="M46 48V12h6v36"/>',
    kfz: '<path d="M8 38l6-14h36l6 14v8H8z"/><circle class="d" cx="18" cy="46" r="4"/><circle class="d" cx="46" cy="46" r="4"/><path class="a" d="M16 30h32"/>',
    invest: '<path d="M10 48h44M14 48V30M26 48V22M38 48V26M50 48V14"/><path class="a" d="M12 26l12-8 12 4 16-12"/>',
    kosten: '<path d="M8 48h48M8 48V8"/><path d="M8 34l46-14"/><path class="a" d="M8 22l46 20"/><circle class="d" cx="33" cy="27" r="3"/>',
    gewinn: '<path d="M8 48h48M8 48V8"/><path class="a" d="M12 44l12-10 10 4 18-22"/><path d="M44 16h8v8"/>',
    renta: '<circle cx="32" cy="30" r="20"/><path class="a" d="M24 38l16-16M25 24h.1M39 36h.1"/>',
  };
  const fig = id => `<svg class="m-fig" viewBox="0 0 64 56" aria-hidden="true">${FIG[id]}</svg>`;
  // An umbrella over rising bars: insurance and investment in one picture.
  const art = still => { const h = i => 14 + i * 12; return `<div class="hero-art m-art bwp-art" aria-hidden="true"><svg viewBox="0 0 224 130"><path class="m-art-grid" d="M0 22H224M0 58H224M0 94H224"/>${[0, 1, 2, 3, 4].map(i => `<rect class="bwp-bar" x="${44 + i * 30}" width="18" rx="5" y="${116 - h(i)}" height="${h(i)}">${still ? '' : `<animate attributeName="height" values="0;${h(i)};${h(i)};0" keyTimes="0;.3;.85;1" dur="7s" begin="${i * 0.25}s" repeatCount="indefinite"/><animate attributeName="y" values="116;${116 - h(i)};${116 - h(i)};116" keyTimes="0;.3;.85;1" dur="7s" begin="${i * 0.25}s" repeatCount="indefinite"/>`}</rect>`).join('')}<g class="bwp-umb">${still ? '' : '<animateTransform attributeName="transform" type="translate" values="0 -4;0 2;0 -4" dur="5s" repeatCount="indefinite"/>'}<path class="bwp-handle" d="M112 14V58a5 5 0 0 1-10 0"/><path d="M40 40a72 30 0 0 1 144 0q-12-8-24 0-12-8-24 0-12-8-24 0-12-8-24 0-12-8-24 0-12-8-24 0z"/></g></svg></div>`; };
  const row = (a, b) => `<tr><td><strong>${rich(a)}</strong></td><td>${rich(b)}</td></tr>`;
  const cheatSheet = () => `<section class="m-section"><h2>Risikopolitische Maßnahmen</h2></section><div class="m-table-wrap"><table class="m-table rows m-dict"><tbody><tr><th>Maßnahme</th><th>Beispiel</th></tr>${[['Vermeiden', 'Auf ein riskantes Geschäft verzichten'], ['Vermindern', 'Alarmanlage, Wartung, Schulung, Risikostreuung'], ['Überwälzen', 'Versicherung, Leasing, Lieferbedingungen'], ['Selbst tragen', 'Kleine Schäden, Selbstbehalt, Rücklagen, Unternehmerrisiko']].map(([a, b]) => row(a, b)).join('')}</tbody></table></div>
    <section class="m-section"><h2>Formelsammlung Investitionsrechnung</h2></section><div class="m-table-wrap"><table class="m-table rows m-dict"><tbody><tr><th>Größe</th><th>Formel</th></tr>${[
    ['Kalk. Zinsen', '(AK + RW) : 2 · Zinssatz'], ['Kalk. Abschreibung', '(AK − RW) : Nutzungsdauer'], ['Gesamtkosten', 'Kalk. Zinsen + kalk. Abschreibung + laufende Betriebskosten'], ['Stückkosten', 'Gesamtkosten : Ausbringungsmenge'], ['Kritische Menge', 'Differenz der Fixkosten : Differenz der variablen Kosten je Einheit'],
    ['Gewinn', 'Erlöse − Gesamtkosten'], ['Ø Kapitaleinsatz', '(AK + RW) : 2'], ['Rentabilität', '(Gewinn + kalk. Zinsen) · 100 : Ø Kapitaleinsatz'], ['Rentabilität bei Kostenersparnis', 'Kostenersparnis · 100 : Ø Kapitaleinsatz'], ['Amortisationsdauer', '(AK − RW) : (Gewinn + kalk. Abschreibung)'], ['Amortisation bei Kostenersparnis', '(AK − RW) : jährliche Kostenersparnis'],
  ].map(([a, b]) => row(a, b)).join('')}</tbody></table></div>
    <section class="m-section"><h2>Versicherungsleistung</h2></section><div class="m-table-wrap"><table class="m-table rows m-dict"><tbody><tr><th>Fall</th><th>Entschädigung</th></tr>${[['Vollversicherung (Summe = Wert)', 'Der ganze Schaden'], ['Überversicherung (Summe > Wert)', 'Der ganze Schaden, nie mehr'], ['Unterversicherung (Summe < Wert)', 'Versicherungssumme · Schaden : Versicherungswert'], ['Selbstbehalt', 'Schaden − Selbstbehalt (mindestens 0)'], ['Erstrisiko', 'Der Schaden bis zur Versicherungssumme']].map(([a, b]) => row(a, b)).join('')}</tbody></table></div>
    <section class="m-section"><h2>Bonus-Malus-Stufen</h2></section><div class="bwp-bm-sheet">${B.BM.map((p, s) => `<div class="${s === 9 ? 'start' : s < 9 ? 'bonus' : 'malus'}" style="--h:${p / 2}%"><b>${p} %</b><span>${s}</span></div>`).join('')}</div><p class="bwp-bm-note">Start bei Stufe 9 · schadenfreies Jahr −1 · jeder Schadensfall +3</p>`;

  // ---- Labs ----
  const range = (k, label, min, max, step, val) => `<label><span>${label}<b data-out="${k}"></b></span><input type="range" min="${min}" max="${max}" step="${step}" value="${val}" data-k="${k}"></label>`;
  const wire = (host, st, paint) => { host.querySelectorAll('[data-k]').forEach(el => el.addEventListener('input', () => { st[el.dataset.k] = Number(el.value); paint(); })); paint(); };
  const out = (host, k, v) => { const el = host.querySelector(`[data-out="${k}"]`); if (el) el.textContent = v; };
  const E = x => `€ ${B.eur(x)}`;
  const LABS = {
    unter(host) {
      const st = { vs: 80000, vw: 100000, dmg: 50000 };
      host.innerHTML = `<p class="m-lab-note">Schieb die Versicherungssumme unter den Versicherungswert und sieh, wie die Entschädigung schrumpft.</p><div class="m-afa-ctl">${range('vs', 'Versicherungssumme', 10000, 200000, 5000, st.vs)}${range('vw', 'Versicherungswert', 10000, 200000, 5000, st.vw)}${range('dmg', 'Schaden', 1000, 200000, 1000, st.dmg)}</div><div class="bwp-under"></div>`;
      wire(host, st, () => {
        st.dmg = Math.min(st.dmg, st.vw); host.querySelector('[data-k="dmg"]').value = st.dmg;
        const pay = st.vs < st.vw ? st.vs * st.dmg / st.vw : st.dmg, kind = st.vs === st.vw ? 'Vollversicherung' : st.vs > st.vw ? 'Überversicherung' : 'Unterversicherung', max = Math.max(st.vs, st.vw);
        out(host, 'vs', E(st.vs)); out(host, 'vw', E(st.vw)); out(host, 'dmg', E(st.dmg));
        host.querySelector('.bwp-under').innerHTML = `<div class="bwp-ubars">${[['Versicherungssumme', st.vs, 'vs'], ['Versicherungswert', st.vw, 'vw'], ['Schaden', st.dmg, 'dm'], ['Entschädigung', pay, 'pay']].map(([l, v, c]) => `<div class="bwp-ub ${c}"><span>${l}</span><i style="--w:${v / max * 100}%"></i><b>${E(v)}</b></div>`).join('')}</div><dl class="m-read"><div><dt>Art</dt><dd class="bwp-txt">${kind}</dd></div><div><dt>Anteil ersetzt</dt><dd>${Math.round(pay / (st.dmg || 1) * 100)} %</dd></div><div><dt>Selbst getragen</dt><dd>${E(st.dmg - pay)}</dd></div></dl>`;
      });
    },
    bonus(host, h) {
      const st = { stage: 9, base: 1200, log: [] };
      host.innerHTML = `<p class="m-lab-note">Fahr ein paar Jahre: Jedes schadenfreie Jahr bringt eine Stufe Bonus, jeder Unfall drei Stufen Malus.</p><div class="m-afa-ctl bwp-one">${range('base', 'Grundprämie (100 %) pro Jahr', 400, 2400, 50, st.base)}</div><div class="bwp-stairs" role="img" aria-label="Bonus-Malus-Stufen">${B.BM.map((p, s) => `<div data-s="${s}" class="${s < 9 ? 'bonus' : s === 9 ? 'start' : 'malus'}" style="--h:${p / 2}%"><i></i><span>${s}</span></div>`).join('')}<div class="bwp-car" aria-hidden="true">🚗</div></div><div class="m-lab-tools bwp-tools"><button type="button" class="button secondary" data-bm="1">${h.icon('check')}Schadenfreies Jahr</button><button type="button" class="button secondary" data-bm="3">${h.icon('close')}Unfall</button><button type="button" class="text-button" data-bm="0">Neu starten</button></div><dl class="m-read"><div><dt>Stufe</dt><dd data-r="s"></dd></div><div><dt>Prozent</dt><dd data-r="p"></dd></div><div><dt>Prämie pro Jahr</dt><dd data-r="e"></dd></div></dl><p class="bwp-log"></p>`;
      const paint = () => {
        const p = B.BM[st.stage], car = host.querySelector('.bwp-car');
        host.querySelectorAll('.bwp-stairs [data-s]').forEach(el => el.classList.toggle('on', Number(el.dataset.s) === st.stage));
        car.style.left = `${(st.stage + 0.5) / 18 * 100}%`; car.style.bottom = `calc(${p / 2}% + 4px)`;
        out(host, 'base', E(st.base)); host.querySelector('[data-r="s"]').textContent = st.stage; host.querySelector('[data-r="p"]').textContent = `${p} %`; host.querySelector('[data-r="e"]').textContent = E(st.base * p / 100);
        host.querySelector('.bwp-log').textContent = st.log.length ? `Verlauf: ${st.log.join(' → ')}` : 'Start bei Stufe 9 (100 %).';
      };
      host.querySelectorAll('[data-bm]').forEach(b => b.addEventListener('click', () => { const d = Number(b.dataset.bm); if (!d) { st.stage = 9; st.log = []; } else { if (!st.log.length) st.log.push(9); st.stage = Math.max(0, Math.min(17, st.stage + (d === 1 ? -1 : 3))); st.log.push(st.stage); if (st.log.length > 12) st.log.shift(); } paint(); }));
      wire(host, st, paint);
    },
    krit(host, h) {
      let c = B.critCase(M.kit.makeRng(Math.floor(Math.random() * 1e9))), q = Math.round(c.crit * 0.6 / 10) * 10;
      host.innerHTML = `<p class="m-lab-note">Zwei Maschinen, unbekannte Auslastung. Zieh die Stunden und sieh, wo sich die Kostengeraden schneiden.</p><p class="bwp-legend"><span class="k1">Maschine 1</span><span class="k2">Maschine 2</span><span class="kc">kritische Menge</span></p><div class="bwp-krit"></div><div class="m-afa-ctl bwp-one"><label><span>Auslastung pro Jahr<b data-out="q"></b></span><input type="range" min="0" step="10" data-q></label></div><dl class="m-read"><div><dt>Kritische Menge</dt><dd data-r="k"></dd></div><div><dt>Maschine 1</dt><dd data-r="a"></dd></div><div><dt>Maschine 2</dt><dd data-r="b"></dd></div><div><dt>Günstiger</dt><dd data-r="w"></dd></div></dl><div class="m-lab-tools"><button type="button" class="button secondary" data-new>${h.icon('spark')}Neue Maschinen</button></div>`;
      const slider = host.querySelector('[data-q]');
      const paint = () => {
        const X = Math.max(1, Math.round(c.crit * 2.2 / 100) * 100), W = 760, H = 300, pad = { l: 56, r: 14, t: 14, b: 30 }, k1 = x => c.m1.fix + c.m1.v * x, k2 = x => c.m2.fix + c.m2.v * x, Y = Math.max(k1(X), k2(X)) * 1.05;
        const px = x => pad.l + x / X * (W - pad.l - pad.r), py = y => H - pad.b - y / Y * (H - pad.t - pad.b), line = f => `M${px(0)} ${py(f(0))}L${px(X)} ${py(f(X))}`;
        slider.max = X; q = Math.min(q, X);
        const ticks = [0, 0.25, 0.5, 0.75, 1].map(t => `<text x="${pad.l - 8}" y="${py(Y * t) + 4}" text-anchor="end">${Math.round(Y * t / 1000)}k</text>`).join('');
        host.querySelector('.bwp-krit').innerHTML = `<svg viewBox="0 0 ${W} ${H}" class="bwp-kchart"><path class="ax" d="M${pad.l} ${pad.t}V${H - pad.b}H${W - pad.r}"/>${ticks}<text x="${W - pad.r}" y="${H - 8}" text-anchor="end">Stunden</text><path class="l1" d="${line(k1)}"/><path class="l2" d="${line(k2)}"/><path class="cr" d="M${px(c.crit)} ${pad.t}V${H - pad.b}"/><circle class="cp" cx="${px(c.crit)}" cy="${py(k1(c.crit))}" r="5"/><path class="qq" d="M${px(q)} ${pad.t}V${H - pad.b}"/><circle class="d1" cx="${px(q)}" cy="${py(k1(q))}" r="6"/><circle class="d2" cx="${px(q)}" cy="${py(k2(q))}" r="6"/></svg>`;
        slider.value = q; out(host, 'q', `${B.eur(q).replace(/,00$/, '')} h`);
        const a = k1(q), b = k2(q);
        host.querySelector('[data-r="k"]').textContent = `${B.eur(c.crit)} h`; host.querySelector('[data-r="a"]').textContent = E(a); host.querySelector('[data-r="b"]').textContent = E(b); host.querySelector('[data-r="w"]').textContent = Math.abs(a - b) < 0.5 ? 'gleich' : a < b ? 'Maschine 1' : 'Maschine 2';
      };
      slider.addEventListener('input', () => { q = Number(slider.value); paint(); });
      host.querySelector('[data-new]').addEventListener('click', () => { c = B.critCase(M.kit.makeRng(Math.floor(Math.random() * 1e9))); q = Math.round(c.crit * 0.6 / 10) * 10; paint(); });
      paint();
    },
    amort(host) {
      const st = { ak: 40000, rw: 4000, nd: 8, g: 6000, i: 5 };
      host.innerHTML = `<p class="m-lab-note">Jedes Jahr fließen Gewinn und Abschreibung zurück. Sobald die Säulen die Linie erreichen, ist das Kapital wieder da.</p><div class="m-afa-ctl">${range('ak', 'Anschaffungskosten', 5000, 120000, 1000, st.ak)}${range('rw', 'Restwert', 0, 30000, 1000, st.rw)}${range('nd', 'Nutzungsdauer (Jahre)', 2, 12, 1, st.nd)}${range('g', 'Gewinn pro Jahr', 0, 30000, 500, st.g)}${range('i', 'Zinssatz (%)', 1, 10, 1, st.i)}</div><div class="bwp-amort"></div>`;
      wire(host, st, () => {
        st.rw = Math.min(st.rw, st.ak); host.querySelector('[data-k="rw"]').value = st.rw;
        const afa = (st.ak - st.rw) / st.nd, back = st.g + afa, need = st.ak - st.rw, am = need / back, kap = (st.ak + st.rw) / 2, zins = kap * st.i / 100, rent = (st.g + zins) * 100 / kap, years = Math.max(st.nd, Math.min(15, Math.ceil(am))), max = Math.max(need, back * years);
        out(host, 'ak', E(st.ak)); out(host, 'rw', E(st.rw)); out(host, 'nd', st.nd); out(host, 'g', E(st.g)); out(host, 'i', `${st.i} %`);
        host.querySelector('.bwp-amort').innerHTML = `<div class="bwp-acols" style="--line:${need / max * 100}%">${Array.from({ length: years }, (_, y) => { const cum = back * (y + 1); return `<div class="${cum >= need - 0.01 ? 'done' : ''}${y >= st.nd ? ' over' : ''}"><i style="--h:${cum / max * 100}%"></i><span>${y + 1}</span></div>`; }).join('')}<em>AK − RW = ${E(need)}</em></div><dl class="m-read"><div><dt>Rückfluss pro Jahr</dt><dd>${E(back)}</dd></div><div><dt>Amortisation</dt><dd>${B.eur(am)} J.</dd></div><div><dt>Rentabilität</dt><dd>${B.eur(rent)} %</dd></div></dl>${am > st.nd ? '<p class="bwp-warn">Die Investition amortisiert sich nicht innerhalb der Nutzungsdauer.</p>' : ''}`;
      });
    },
  };

  window.WWBwpCourse = {
    key: 'bwp', subject: 'BWP', engine: B, topics: TOPICS, fig, art, cheatSheet, labs: LABS, sheetTitle: 'Formeln', focusClass: 'bwp-focus',
    focus: { label: 'Nur SA-Stoff', topics: B.SA_TOPICS, note: 'Üben, Fortschritt und Test nur mit dem Stoff der Schularbeit. Die Extras unten bleiben trotzdem offen.' },
    line: `Versicherungen und Investitionsrechnung · ${TOPICS.length} Themen · Rechnen wie in der Excel-Lösung`, examTitle: 'Versicherungen und Investitionen',
    testIntro: 'Aufgaben wie in der SA: Kostenvergleich in der Excel-Tabelle, Fallstudie mit Gewinn, Rentabilität und Amortisation, Versicherungen mit Risikopolitik und Investitionstheorie. Ohne Tipps und ohne Sofort-Feedback, am Ende bekommst du Punkte und alle Lösungen.',
    testSizes: [['full', 4, 'Ganze SA', '4 Aufgaben · etwa 50 Minuten'], ['inv', 3, 'Nur Investitionsrechnung', '3 Rechenaufgaben · etwa 35 Minuten'], ['short', 2, 'Kurztest', '2 Aufgaben · etwa 20 Minuten']],
  };
})();
